function defaultMeta(){return {version:2,runs:0,wins:0,bankruptcies:0,totalDays:0,careerPoints:0,bestNetWorth:0,unlockedOrigins:['canbang'],discoveredEvents:[],discoveredChains:[],discoveredFacilities:[],discoveredCharacters:[],endings:[],titles:[],worldSeeds:[],history:[],notebook:{patterns:{},rumorSources:{}},achievements:{contractsCompleted:0,debtRepaid:0,trades:0,repairs:0,facilitiesBuilt:0,maxReputation:0,maxNetWorth:0,longRoutes:0}};}
function loadMeta(){try{const d=defaultMeta(),x=Object.assign(d,JSON.parse(localStorage.getItem(META_KEY)||'{}'));x.notebook=Object.assign(d.notebook,x.notebook||{});x.notebook.patterns=x.notebook.patterns||{};x.notebook.rumorSources=x.notebook.rumorSources||{};x.achievements=Object.assign(d.achievements,x.achievements||{});updateUnlocksForMeta(x);return x;}catch{return defaultMeta();}}
function saveMeta(){localStorage.setItem(META_KEY,JSON.stringify(meta));}
function loadSlot(i){try{return JSON.parse(localStorage.getItem(SLOT_KEY(i)));}catch{return null;}}
function save(){if(!state)return;state.updatedAt=Date.now();localStorage.setItem(SLOT_KEY(slot),JSON.stringify(state));}
function eraseSlot(i){localStorage.removeItem(SLOT_KEY(i));}
function esc(s){return String(s||'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));}
function rnd(a,b){return Math.floor(Math.random()*(b-a+1))+a;}
function pick(a){return a[Math.floor(Math.random()*a.length)];}
function clamp(v,a,b){return Math.max(a,Math.min(b,v));}
function money(v){const sign=v<0?'-':''; v=Math.abs(v); return sign + (v>=1000 ? (v/1000).toLocaleString('vi-VN',{maximumFractionDigits:2})+' tỷ' : v.toLocaleString('vi-VN',{maximumFractionDigits:1})+' tr');}
const pname=id=>PORTS.find(p=>p.id===id)?.name||id;
const gname=id=>GOODS.find(g=>g.id===id)?.name||id;
const sdef=id=>SHIP_TYPES.find(s=>s.id===id);
function shortestRoute(from,to){
 if(from===to)return{path:[from],baseDays:0};
 const dist={},prev={},open=PORTS.map(p=>p.id);for(const id of open)dist[id]=Infinity;dist[from]=0;
 while(open.length){open.sort((a,b)=>dist[a]-dist[b]);const cur=open.shift();if(cur===to)break;if(!Number.isFinite(dist[cur]))break;for(const [n,w] of Object.entries(ROUTES[cur]||{})){const nd=dist[cur]+w;if(nd<dist[n]){dist[n]=nd;prev[n]=cur;}}}
 if(!Number.isFinite(dist[to]))return null;const path=[];let cur=to;while(cur){path.unshift(cur);if(cur===from)break;cur=prev[cur];}return path[0]===from?{path,baseDays:dist[to]}:null;
}
function routeDaysForShip(ship,from,to){const r=shortestRoute(from,to);if(!r)return Infinity;const speed=sdef(ship.type)?.speed||1;let days=0;for(let i=0;i<r.path.length-1;i++)days+=Math.max(1,Math.ceil((ROUTES[r.path[i]]?.[r.path[i+1]]||1)/speed));return days;}
function routeInfoForShip(ship,from,to){const r=shortestRoute(from,to);if(!r)return null;return{...r,days:routeDaysForShip(ship,from,to),direct:r.path.length===2};}
function routePathText(path){return(path||[]).map(pname).join(' → ');}
function contractCargoQty(ship){return Object.values(ship.contractCargo||{}).reduce((sum,x)=>sum+(x?.qty||0),0);}
function contractCargoFor(ship,contractId){return ship.contractCargo?.[contractId]||null;}
function contractRouteBaseDays(c){return shortestRoute(c.from,c.to)?.baseDays??Infinity;}
function contractRewardEstimate(from,to,good,qty){const baseDays=shortestRoute(from,to)?.baseDays||1,cargoValue=(GOODS.find(g=>g.id===good)?.base||20)*qty,cycle=ECON_CYCLES.find(c=>c.id===state?.economy?.cycle)||ECON_CYCLES[0],baseFee=8+qty*.5,distanceFee=baseDays*(4+qty*.35),valueFee=cargoValue*.02,cycleMul=clamp(.94+(cycle.price-1)*.55,.9,1.12);return Math.max(12,Math.round((baseFee+distanceFee+valueFee)*cycleMul));}
function bestShipEstimateToContract(c){let best=null;for(const ship of state.ships||[]){const cap=sdef(ship.type)?.cap||50;if(cap<c.qty)continue;const start=ship.dest||ship.port,wait=ship.dest?Math.max(0,ship.eta||0):0,pickup=routeDaysForShip(ship,start,c.from),delivery=routeDaysForShip(ship,c.from,c.to),total=wait+pickup+delivery;if(!Number.isFinite(total))continue;if(!best||total<best.total)best={ship,pickup,delivery,wait,total};}return best;}
function contractFeasibility(c){const best=bestShipEstimateToContract(c);if(!best)return{ok:false,label:'Chưa có tàu đủ sức chở',days:Infinity};const left=c.deadline-state.day,buffer=left-best.total;return{ok:buffer>=1,label:buffer>=4?'Thoải mái':buffer>=1?'Có thể làm':'Rất gấp',days:best.total,buffer,ship:best.ship,pickup:best.pickup,delivery:best.delivery};}
function fuelCostFrom(ship,from,to){const days=routeDaysForShip(ship,from,to);if(!Number.isFinite(days))return Infinity;let cost=days*(sdef(ship.type)?.fuel||1)*8;const owned=state.facilities?.[from]?.owned||[];if(owned.includes('fuel'))cost*=.8;if(state.origin==='hangrong'&&days>=2)cost*=.85;if(state.effects.some(e=>e.type==='energyCrisis'))cost*=1.3;return Math.round(cost);}
function contractEstimatedFuel(c,best=bestShipEstimateToContract(c)){if(!best)return Infinity;const start=best.ship.dest||best.ship.port,pick=best.ship.dest?fuelCostFrom(best.ship,start,c.from):fuelCostFrom(best.ship,best.ship.port,c.from),deliver=fuelCostFrom(best.ship,c.from,c.to);return pick+deliver;}
function contractRewardWithPickup(c){const best=bestShipEstimateToContract(c),base=contractRewardEstimate(c.from,c.to,c.good,c.qty),pickupBonus=best?Math.round(best.pickup*(3+c.qty*.15)):0,fuel=best?contractEstimatedFuel(c,best):0,minMargin=10+c.qty*.25;return Math.round(Math.max(base+pickupBonus,fuel+minMargin));}
function normalizeContract(c){if(!c)return c;c.routeBaseDays=contractRouteBaseDays(c);c.balanceVersion=2;const fairReward=contractRewardWithPickup(c);if(!c.reward||c.reward>Math.max(220,fairReward*2.5))c.reward=fairReward;if(!c.deadline||c.deadline<=state.day){const best=bestShipEstimateToContract(c),need=best?.total||c.routeBaseDays||4;c.deadline=state.day+need+rnd(3,6);}return c;}
function tip(text){return `<span class="help" title="${esc(text)}">ⓘ</span>`;}
function ensureMetaArray(key,val){if(!meta[key].includes(val)){meta[key].push(val); saveMeta();}}

function createMarkets(){const markets={};
 for(const p of PORTS){markets[p.id]={};
  for(const g of GOODS){const bias=(p.prod[g.id]||0)-(p.cons[g.id]||0); const stock=clamp(80+bias*3+rnd(-15,18),20,180); const price=Math.max(4,g.base*(1+(70-stock)/120)+rnd(-2,2)); markets[p.id][g.id]={stock,price,trend:0,history:[price]};}
 }
 return markets;
}
