function originAchievementValue(o,m=meta){const a=m.achievements||{};const r=ORIGIN_UNLOCKS[o.id];if(!r)return Infinity;if(r.metric==='runs')return m.runs||0;if(r.metric==='broker')return (a.contractsCompleted>=8&&a.maxReputation>=40)?1:0;if(r.metric==='enterprise')return (a.maxNetWorth>=2000&&a.maxReputation>=60)?1:0;return a[r.metric]||0;}
function originUnlockReady(o,m=meta){if(o.id==='canbang')return true;const r=ORIGIN_UNLOCKS[o.id];return (m.careerPoints||0)>=o.unlock || (r&&originAchievementValue(o,m)>=r.goal);}
function originUnlockText(o,m=meta){if(o.id==='canbang')return 'Có sẵn ngay từ đầu.';const r=ORIGIN_UNLOCKS[o.id],v=originAchievementValue(o,m);let progress='';if(r){if(r.metric==='broker')progress=`hiện ${m.achievements.contractsCompleted||0}/8 hợp đồng · danh tiếng cao nhất ${m.achievements.maxReputation||0}/40`;else if(r.metric==='enterprise')progress=`tài sản cao nhất ${money(m.achievements.maxNetWorth||0)}/2 tỷ · danh tiếng cao nhất ${m.achievements.maxReputation||0}/60`;else progress=`tiến độ ${Math.min(v,r.goal)}/${r.goal}`;}return `Mở nhanh: ${r?.text||'đạt thành tích riêng'} (${progress}). Hoặc đủ ${o.unlock} Điểm sự nghiệp: ${Math.min(m.careerPoints||0,o.unlock)}/${o.unlock}.`;}
function updateUnlocksForMeta(m=meta){if(!m.unlockedOrigins)m.unlockedOrigins=['canbang'];for(const o of ORIGINS)if(originUnlockReady(o,m)&&!m.unlockedOrigins.includes(o.id))m.unlockedOrigins.push(o.id);return m;}
function syncCareerAchievement(key,value,mode='add'){meta.achievements=meta.achievements||defaultMeta().achievements;if(mode==='max')meta.achievements[key]=Math.max(meta.achievements[key]||0,value);else meta.achievements[key]=(meta.achievements[key]||0)+value;meta.achievements.maxReputation=Math.max(meta.achievements.maxReputation||0,state?.reputation||0);meta.achievements.maxNetWorth=Math.max(meta.achievements.maxNetWorth||0,state?netWorth():0);const before=new Set(meta.unlockedOrigins||[]);updateUnlocksForMeta(meta);if(state){state.seenUnlocks=state.seenUnlocks||[];for(const o of ORIGINS){if(meta.unlockedOrigins.includes(o.id)&&!before.has(o.id)&&!state.seenUnlocks.includes(o.id)){state.seenUnlocks.push(o.id);pushNews('Mở khóa kiểu khởi đầu',`${o.name} đã được mở cho các hành trình sau.`,'Mở khóa');}}}saveMeta();}
function ensureActivity(s){s.activity=s.activity||{level:100,idleDays:0,lastActionDay:s.day||1,unpaidMonths:0};s.emotion=s.emotion||{phase:'neutral',lastHighDay:-99,opportunityCooldown:0,lastPacedDay:-99};return s;}
function recordActivity(points=8,label=''){if(!state)return;ensureActivity(state);state.activity.lastActionDay=state.day;state.activity.idleDays=0;state.activity.level=clamp(state.activity.level+points,0,100);if(label)state.activity.lastAction=label;}
function activityLabel(){ensureActivity(state);const v=state.activity.level;return v>=70?'Sôi động':v>=40?'Bình thường':v>=20?'Trầm':'Ngủ đông';}
function processActivityBeforeAdvance(){ensureActivity(state);const acted=state.activity.lastActionDay===state.day;if(acted){state.activity.level=clamp(state.activity.level+2,0,100);state.activity.idleDays=0;}else{state.activity.idleDays++;state.activity.level=clamp(state.activity.level-2,0,100);}if(state.activity.idleDays===30)pushNews('Công ty bắt đầu trầm xuống','30 ngày gần đây gần như không có hoạt động mới. Cơ hội hợp đồng sẽ ít dần nếu bạn tiếp tục đứng yên.','Vận hành');if(state.activity.idleDays===90)pushNews('Doanh nghiệp gần như ngủ đông','Khách hàng ít nhớ tới công ty hơn. Chi phí vận hành vẫn tiếp tục phát sinh mỗi tháng.','Cảnh báo');}
function insurancePlan(id){return INSURANCE_PLANS.find(x=>x.id===id)||INSURANCE_PLANS[2];}
function shipStatus(s){if(s.dest)return `🔵 Đang đi · còn ${s.eta} ngày → ${pname(s.dest)}`;if(s.condition<35)return `🔴 Cần sửa gấp · ${pname(s.port)}`;if(s.condition<65)return `🟠 Cần bảo dưỡng · ${pname(s.port)}`;return `🟢 Đang đậu · ${pname(s.port)}`;}
function monthlyOperatingCost(){const companyBase=3,staff=Math.max(6,state.monthlySalary||10),shipPack=state.ships.reduce((sum,s)=>{const t=sdef(s.type)||SHIP_TYPES[0],ins=insurancePlan(s.insurance);return sum+2.2+t.maint*.65+ins.premium;},0),facPack=Object.values(state.facilities||{}).reduce((sum,f)=>sum+(f.owned||[]).length*.8,0);return Math.round((companyBase+staff+shipPack+facPack)*10)/10;}
function operatingCostBreakdown(){const uninsured=state.ships.filter(s=>(s.insurance||'standard')==='none').length;return `Đã gom các khoản nhỏ thành một mục: nhân sự, bảo hiểm đang chọn, bảo trì nhẹ, dự phòng đăng kiểm, văn phòng, neo đậu cơ bản và cơ sở.${uninsured?` ${uninsured} tàu đang không mua bảo hiểm nên phí thấp hơn nhưng rủi ro tài chính cao hơn.`:''}`;}
function emotionLabel(){ensureActivity(state);if(state.emotion.phase==='high')return 'Đang có cơ hội nóng';if(state.emotion.phase==='cooldown')return 'Đang hạ nhiệt';if(state.cash<30)return 'Đang căng dòng tiền';return 'Nhịp thị trường bình thường';}
function celebrateBigWin(text){ensureActivity(state);state.emotion.phase='high';state.emotion.lastHighDay=state.day;state.emotion.opportunityCooldown=rnd(14,24);pushNews('🎯 Trúng mánh!',text,'Cơ hội');toast('Trúng mánh! Kiểm tra Bản tin sáng để xem chi tiết.');}
function maybePacedEmotionEvent(){ensureActivity(state);const e=state.emotion;if(e.opportunityCooldown>0)e.opportunityCooldown--;if(e.phase==='high'&&state.day-e.lastHighDay>=5){e.phase='cooldown';e.lastPacedDay=state.day;const p=pick(PORTS);state.effects.push({type:'marketCool',port:p.id,days:rnd(3,6)});pushNews('Thị trường hạ nhiệt',`Sau đợt sôi động, ${p.name} bắt đầu cân bằng lại. Giá có thể bớt nóng trong vài ngày.`,'Thị trường');return true;}if(e.phase==='cooldown'&&state.day-e.lastPacedDay>=5)e.phase='neutral';const stressed=state.cash<35||state.activity.level<35,due=state.day-e.lastHighDay>18&&e.opportunityCooldown<=0;if(due||(stressed&&state.day-e.lastPacedDay>10)){startOpportunityEvent(stressed);return true;}return false;}
function startOpportunityEvent(recovery=false){ensureActivity(state);const port=pick(PORTS),good=pick(GOODS),kind=pick(['discount','contract','clearance']);state.emotion.phase='high';state.emotion.lastHighDay=state.day;state.emotion.lastPacedDay=state.day;state.emotion.opportunityCooldown=rnd(16,26);if(kind==='discount'){const m=state.markets[port.id][good.id],pct=recovery?rnd(32,42):rnd(25,38);m.price=Math.max(3,m.price*(1-pct/100));state.effects.push({type:'deepDiscount',port:port.id,good:good.id,days:rnd(3,5)});pushNews('🔥 Xả kho giảm sâu',`${good.name} tại ${port.name} vừa giảm khoảng ${pct}% trong một đợt xả hàng ngắn. Đây là cơ hội thật nhưng bạn vẫn phải tính đường vận chuyển và đầu ra.`,'Cơ hội');addObservation('Cơ hội giảm giá sâu',`${good.name} tại ${port.name} giảm mạnh. Giá rẻ không đồng nghĩa chắc chắn có lời nếu đầu ra không tốt.`);}else if(kind==='contract'){generateContractsIfNeeded(true);if(state.contracts[0]){state.contracts[0].reward=Math.round(state.contracts[0].reward*(recovery?1.65:1.45));state.contracts[0].deadline+=2;}pushNews('🔥 Hợp đồng béo','Một khách hàng cần giao gấp và chấp nhận trả cao hơn bình thường. Hợp đồng mới đã xuất hiện trong tab Hợp đồng.','Cơ hội');}else{const bonus=recovery?rnd(12,20):rnd(8,16);state.cash+=bonus;pushNews('🔥 Khoản thu bất ngờ',`Một khoản đối soát cũ được thanh toán, công ty nhận thêm ${money(bonus)}. Không lớn tới mức phá cân bằng nhưng đủ tạo khoảng thở.`,'Cơ hội');}return true;}
